TLM.f("Sancti/01-28",{"officium":"S. Petri Nolasci Confessoris","rule":["vide C5b;","Gloria"],"fallback":"Commune/C5b","from":{"Introitus":"Commune/C5b","Lectio":"Commune/C5b","Graduale":"Commune/C5b","GradualeP":"Commune/C5b","Tractus":"Commune/C5b","Evangelium":"Commune/C5b","Offertorium":"Commune/C5b","Communio":"Commune/C5b"},"sections":{"Introitus":[{"k":"ref","la":"Ps 91:13-14"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur: plantátus in domo Dómini: in átriis domus Dei nostri."},{"k":"ref","la":"Ps 91:2"},{"k":"text","la":"Bonum est confitéri Dómino: et psállere nómini tuo, Altíssime."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur: plantátus in domo Dómini: in átriis domus Dei nostri."}],"Oratio":[{"k":"text","la":"Deus, qui in tuæ caritátis exémplum ad fidélium redemptiónem sanctum Petrum Ecclésiam tuam nova prole fœcundáre divínitus docuísti: ipsíus nobis intercessióne concéde; a peccáti servitúte solútis, in cœlésti pátria perpétua libertáte gaudére:"},{"k":"macro","name":"Qui vivis"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Corínthios"},{"k":"ref","la":"1 Cor 4:9-14"},{"k":"text","la":"Fratres: Spectáculum facti sumus mundo et Angelis et homínibus. Nos stulti propter Christum, vos autem prudéntes in Christo: nos infírmi, vos autem fortes: vos nóbiles, nos autem ignóbiles. Usque in hanc horam et esurímus, et sitímus, et nudi sumus, et cólaphis cǽdimur, et instábiles sumus, et laborámus operántes mánibus nostris: maledícimur, et benedícimus: persecutiónem pátimur, et sustinémus: blasphemámur, et obsecrámus: tamquam purgaménta hujus mundi facti sumus, ómnium peripséma usque adhuc. Non ut confúndant vos, hæc scribo, sed ut fílios meos caríssimos móneo: in Christo Jesu, Dómino nostro."}],"Graduale":[{"k":"ref","la":"Ps 36:30-31"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium."},{"k":"text","la":"Lex Dei ejus in corde ipsíus: et non supplantabúntur gressus ejus. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 111:1"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja"},{"k":"ref","la":"Ps 111:1"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis. Allelúja"},{"k":"ref","la":"Osee 14:6"},{"k":"text","la":"Justus germinábit sicut lílium: et florébit in ætérnum ante Dóminum. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 36:30-31"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium."},{"k":"text","la":"Lex Dei ejus in corde ipsíus: et non supplantabúntur gressus ejus.","mark":"V"},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 12:32-34"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Nolíte timére, pusíllus grex, quia complácuit Patri vestro dare vobis regnum. Véndite quæ possidétis, et date eleemósynam. Fácite vobis sácculos, qui non veteráscunt, thesáurum non deficiéntem in cœlis: quo fur non apprópiat, neque tínea corrúmpit. Ubi enim thesáurus vester est, ibi et cor vestrum erit."}],"Offertorium":[{"k":"ref","la":"Ps 20:2-3"},{"k":"text","la":"In virtúte tua, Dómine, lætábitur justus, et super salutáre tuum exsultábit veheménter: desidérium ánimæ ejus tribuísti ei. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Laudis tibi, Dómine, hóstias immolámus in tuórum commemoratióne Sanctórum quibus nos et præséntibus éxui malis confídimus et futúris."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 19:28-29"},{"k":"text","la":"Amen, dico vobis: quod vos, qui reliquístis ómnia et secúti estis me, céntuplum accipiétis, et vitam ætérnam possidébitis. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Refécti cibo potúque cœlésti, Deus noster, te súpplices exorámus: ut, in cujus hæc commemoratióne percépimus, ejus muniámur et précibus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"6b4668e2db0b0991":{"t":"Ps 91, 13-14, Ps 91, 2\n(Ps 91, 13-14) Kao palma cvjeta i kao libanski cedar raste pravednik zasađen u Gospodnjem domu, u trijemovima hrama Boga našega. (Ps 91, 2) Dobro je slaviti Gospodina, i pjevati tvojemu imenu, Svevišnji.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 91, 13-14) Kao palma cvjeta i kao libanski cedar raste pravednik zasađen u Gospodnjem domu, u trijemovima hrama Boga našega."},"061eb13ae6e18cd1":{"t":"<i>Pomolimo se</i>.\nBože, koji si za dokaz svoje ljubavi nadahnuo svetoga Petra da osnuje u tvojoj Crkvi novi red za otkupljenje vjernih, daj nam po njegovu zagovoru da se oslobođeni od ropstva grijeha radujemo vječnoj slobodi u nebeskoj domovini:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"641c47c9ff3544c0":{"t":"1 Kor 4, 9-15\nČitanje Poslanice bl. Pavla apostola Korinćanima. Braćo! Svijet i anđeli i ljudi upiru u nas pogled. Mi smo kao ludi radi Krista, a vi mudri u Kristu; mi smo slabi, a vi jaki; vi plemeniti, a mi prezreni. Sve do sada, i gladujemo, i žeđamo, i goli smo, i ćuškaju nas, i nemamo trajna boravišta i mučimo se radom svojih ruku. Psuju nas, a mi blagoslivljamo, progone nas, a mi trpimo, kleveću nas, a mi molimo, postali smo kao smeće ovoga svijeta, kao izmet svih sve do sada. Ovoga ne pišem zato da vas postidim, nego da vas opomenem kao svoju predragu djecu: u Isusu Kristu, Gospodinu našemu."},"6d9e364d27075ba3":{"t":"Ps 36, 30-31\nPravednikova usta raspravljaju o mudrosti i njegov jezik govori o pravdi. Zakon mu je Božji u srcu, i noge mu neće posrnuti.\n\nPs 111, 1\n<i>aleluja</i>, <i>aleluja</i>.\nBlago čovjeku koji se boji Gospodina i koji uživa u njegovim zapovijedima. <i>Aleluja</i>."},"1cac10fd63222759":{"t":"Lk 12, 32-34\nSlijedi sveto Evanđelje po Luki. U ono vrijeme reče Isus svojim učenicima: Nemojte se bojati, malo stado, jer je vaš Otac odlučio dati vam kraljevstvo. Prodajte što imate i dajte milostinju. Načinite sebi torbe koje neće ostarjeti, neprolazno blago na nebu, kamo se ne približava lupež, niti izjeda moljac. Jer gdje je vaše blago, ondje će biti i vaše srce."},"4e296f3326e0e479":{"t":"Ps 20, 2-3\nU jakosti tvojoj, Gospodine, raduje se pravednik i kliče radi tvoga spasenja, jer si mu ispunio želju srca njegova."},"18a58d3552d982fb":{"t":"Posvećujemo ti, Gospodine, žrtve hvale na spomen tvojih svetih i uzdamo se da ćeš nas po njima izbaviti od sadašnjih i od budućih zala.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"d76f89b9ab1556d0":{"t":"Mt 19, 28 i 29\nZaista vam kažem da ćete vi koji ste ostavili sve i pošli za mnom primiti stostruko i baštiniti život vječni."},"77eef81bf0c58a4e":{"t":"<i>Pomolimo se</i>.\nOkrijepljeni nebeskim jelom i pićem ponizno te molimo, Bože naš, da budemo zaštićeni molitvama onoga na čiji smo to spomen primili.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"625620eaa290262e":{"t":"Ps 36, 30-31\nPravednikova usta raspravljaju o mudrosti i njegov jezik govori o pravdi. Zakon mu je Božji u srcu, i noge mu neće posrnuti.\n\nPs 111, 1-3\nBlago čovjeku koji se boji Gospodina i koji uživa u njegovim zapovijedima. Silno će biti na zemlji njegovo potomstvo, rod će pravednika biti blagoslovljen. U njegovu je domu slava i bogatstvo, i njegova pravednost ostaje u vijeke vjekova."}}});
